// MsgServer is the server API for Msg service.
type MsgServer interface {
	// UpdateTaskParams applies one governance Task params version.
	UpdateTaskParams(context.Context, *MsgUpdateTaskParams) (*MsgUpdateTaskParamsResponse, error)
	// CreateSession derives one new session from the signer's SessionNonce.
	CreateSession(context.Context, *MsgCreateSession) (*MsgCreateSessionResponse, error)
	// UpdateSessionKey sets or clears authorization using the owner's wallet.
	UpdateSessionKey(context.Context, *MsgUpdateSessionKey) (*MsgUpdateSessionKeyResponse, error)
	// CancelOrder skips one unused order sequence.
	CancelOrder(context.Context, *MsgCancelOrder) (*MsgCancelOrderResponse, error)
	// SubmitWorkerHandraises is the single Task admission and Worker candidate
	// entry; it replaces the deleted MsgAssign.
	// SubmitWorkerHandraises executes the SubmitWorkerHandraises operation.
	SubmitWorkerHandraises(context.Context, *MsgSubmitWorkerHandraises) (*MsgSubmitWorkerHandraisesResponse, error)
	// SubmitInferReceipt accepts the winner Worker's inference receipt; it
	// replaces the deleted MsgInferReceiptCommitOnly.
	// SubmitInferReceipt executes the SubmitInferReceipt operation.
	SubmitInferReceipt(context.Context, *MsgSubmitInferReceipt) (*MsgSubmitInferReceiptResponse, error)
	// SubmitWorkerEvidence accepts one strict-encoded objective Worker proof.
	SubmitWorkerEvidence(context.Context, *MsgSubmitWorkerEvidence) (*MsgSubmitWorkerEvidenceResponse, error)
	// SubmitVerifierValueEvidence is registered but returns ERR_NOT_ACTIVATED.
	SubmitVerifierValueEvidence(context.Context, *MsgSubmitVerifierValueEvidence) (*MsgSubmitVerifierValueEvidenceResponse, error)
	// SubmitVerifierHandraises is the single Open Verify entry; it replaces the
	// deleted MsgOpenVerify.
	// SubmitVerifierHandraises executes the SubmitVerifierHandraises operation.
	SubmitVerifierHandraises(context.Context, *MsgSubmitVerifierHandraises) (*MsgSubmitVerifierHandraisesResponse, error)
	// SubmitAnchorOpening records the winner Worker's opening of the sampled anchor positions (ADR-0040).
	SubmitAnchorOpening(context.Context, *MsgSubmitAnchorOpening) (*MsgSubmitAnchorOpeningResponse, error)
	// SubmitAnchorProof records the winner Worker's proof package over its opening (ADR-0040 v2).
	SubmitAnchorProof(context.Context, *MsgSubmitAnchorProof) (*MsgSubmitAnchorProofResponse, error)
	// SubmitAnchorAuditResult records a selected Verifier's anchor audit verdicts (ADR-0040).
	SubmitAnchorAuditResult(context.Context, *MsgSubmitAnchorAuditResult) (*MsgSubmitAnchorAuditResultResponse, error)
	// SubmitAnchorValidatorVote records a bonded validator's verdict on the Worker's anchor proof (ADR-0040 v4).
	SubmitAnchorValidatorVote(context.Context, *MsgSubmitAnchorValidatorVote) (*MsgSubmitAnchorValidatorVoteResponse, error)
	// ReportDataUnavailable records one selected Verifier's data-availability report.
	ReportDataUnavailable(context.Context, *MsgReportDataUnavailable) (*MsgReportDataUnavailableResponse, error)
	// SubmitBuilderEvidence accepts one closed typed objective Builder proof.
	// It moved here from hub.v1.Msg: the Task module owns the
	// envelope payload and the Task authority, and it returns the shared receipt
	// directly instead of a module-local Response wrapper.
	// SubmitBuilderEvidence executes the SubmitBuilderEvidence operation.
	SubmitBuilderEvidence(context.Context, *MsgSubmitBuilderEvidence) (*types.BuilderObjectiveEvidenceReceiptV2, error)
	// SubmitVerifyCommit replaces the deleted MsgCommit.
	SubmitVerifyCommit(context.Context, *MsgSubmitVerifyCommit) (*MsgSubmitVerifyCommitResponse, error)
	// BatchSubmitVerifyCommit replaces the deleted MsgBatchCommit.
	BatchSubmitVerifyCommit(context.Context, *MsgBatchSubmitVerifyCommit) (*MsgBatchSubmitVerifyCommitResponse, error)
	// SubmitVerifyResult replaces the deleted MsgResult.
	SubmitVerifyResult(context.Context, *MsgSubmitVerifyResult) (*MsgSubmitVerifyResultResponse, error)
	// BatchSubmitVerifyResult replaces the deleted MsgBatchResult.
	BatchSubmitVerifyResult(context.Context, *MsgBatchSubmitVerifyResult) (*MsgBatchSubmitVerifyResultResponse, error)
	// OpenChallengeRound opens the fixed funded verification round 2.
	OpenChallengeRound(context.Context, *MsgOpenChallengeRound) (*MsgOpenChallengeRoundResponse, error)
	// SettleTask derives and atomically applies the sole Phase 0 settlement plan.
	SettleTask(context.Context, *MsgSettleTask) (*MsgSettleTaskResponse, error)
	// SweepDeadline is the single bounded deadline runner; it replaces the deleted
	// MsgSweepExpiredTask and MsgSessionSweep.
	// SweepDeadline executes the SweepDeadline operation.
	SweepDeadline(context.Context, *MsgSweepDeadline) (*MsgSweepDeadlineResponse, error)
}

